import java.util.*;
final class Json {
 static String write(Object v){if(v==null)return "null";if(v instanceof Number||v instanceof Boolean)return v.toString();if(v instanceof Map){StringJoiner j=new StringJoiner(",","{","}");((Map<?,?>)v).forEach((k,x)->j.add(write(k.toString())+":"+write(x)));return j.toString();}if(v instanceof Iterable){StringJoiner j=new StringJoiner(",","[","]");for(Object x:(Iterable<?>)v)j.add(write(x));return j.toString();}StringBuilder b=new StringBuilder("\"");for(char c:v.toString().toCharArray()){if(c=='"'||c=='\\')b.append('\\').append(c);else if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}return b.append('"').toString();}
 static Map<String,Object> object(String s){Parser p=new Parser(s);Object v=p.value(0);p.ws();if(p.i!=s.length()||!(v instanceof Map))throw new IllegalArgumentException("Expected JSON object");return (Map<String,Object>)v;}
 private static final class Parser{
  final String s;int i;Parser(String s){this.s=s;}void ws(){while(i<s.length()&&Character.isWhitespace(s.charAt(i)))i++;}
  Object value(int depth){if(depth>32)throw new IllegalArgumentException("JSON nesting");ws();if(i>=s.length())throw new IllegalArgumentException("Incomplete JSON");char c=s.charAt(i++);
   if(c=='"'){StringBuilder b=new StringBuilder();while(i<s.length()){c=s.charAt(i++);if(c=='"')return b.toString();if(c=='\\'){c=s.charAt(i++);switch(c){case 'u':b.append((char)Integer.parseInt(s.substring(i,i+4),16));i+=4;break;case 'n':b.append('\n');break;case 'r':b.append('\r');break;case 't':b.append('\t');break;case 'b':b.append('\b');break;case 'f':b.append('\f');break;case '"':case '\\':case '/':b.append(c);break;default:throw new IllegalArgumentException("JSON escape");}}else{if(c<32)throw new IllegalArgumentException("Control character");b.append(c);}}throw new IllegalArgumentException("Unclosed string");}
   if(c=='{'){Map<String,Object> m=new LinkedHashMap<>();ws();if(i<s.length()&&s.charAt(i)=='}'){i++;return m;}while(true){Object key=value(depth+1);if(!(key instanceof String))throw new IllegalArgumentException("JSON key");ws();if(s.charAt(i++)!=':')throw new IllegalArgumentException("JSON colon");if(m.containsKey(key))throw new IllegalArgumentException("Duplicate key");m.put((String)key,value(depth+1));ws();c=s.charAt(i++);if(c=='}')return m;if(c!=',')throw new IllegalArgumentException("JSON comma");}}
   if(c=='['){List<Object>a=new ArrayList<>();ws();if(i<s.length()&&s.charAt(i)==']'){i++;return a;}while(true){a.add(value(depth+1));ws();c=s.charAt(i++);if(c==']')return a;if(c!=',')throw new IllegalArgumentException("JSON comma");}}
   i--;int start=i;while(i<s.length()&&",]} \r\n\t".indexOf(s.charAt(i))<0)i++;String token=s.substring(start,i);if(token.equals("null"))return null;if(token.equals("true"))return true;if(token.equals("false"))return false;double number=Double.parseDouble(token);if(!Double.isFinite(number))throw new IllegalArgumentException("JSON number");return number;
  }
 }
}
